}
.cbf-page .cbf-demo-controls {
  margin-block-end: var(--spacing-500);
}
.cbf-demo-controls__row {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--spacing-400);
}
.cbf-demo-controls__flag {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-200);
  max-width: 42ch;
}
.cbf-demo-controls__flag p {
  margin: 0;
  color: var(--color-content-default-secondary);
}
.cbf-demo-controls__toggles {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-500);
  align-items: flex-end;
}
.cbf-page .cbf-app-panel {
  overflow: visible;
}
.cbf-lipd__panel {
  padding-block-start: var(--spacing-400);
}
.cbf-summary__head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--spacing-300);
}
.cbf-summary__title {
  margin: 0;
  font-size: var(--font-size-400, 1.125rem);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.cbf-summary__actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-200);
}
.cbf-summary__modified {
  margin: 0 0 var(--spacing-300);
  color: var(--color-content-default-tertiary);
}
.cbf-summary__basics {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-500);
  align-items: flex-start;
}
.cbf-summary__basics-main {
  flex: 1;
  min-width: min(100%, 420px);
}
.cbf-summary__dl {
  display: grid;
  grid-template-columns: 210px 1fr;
  margin: 0;
}
.cbf-summary__dl > dt {
  grid-column: 1;
  text-align: right;
  padding: var(--spacing-300) var(--spacing-400);
  border-top: 1px solid var(--color-border-default-subtle, var(--color-border-default));
  color: var(--color-content-default-secondary);
  font-weight: var(--typography-font-weight-medium);
}
.cbf-summary__dl > dt:first-of-type,
.cbf-summary__dl > dt:first-of-type + dd {
  border-top: 0;
}
.cbf-summary__dl > dd {
  grid-column: 2;
  margin: 0;
  padding: var(--spacing-300) var(--spacing-400);
  border-top: 1px solid var(--color-border-default-subtle, var(--color-border-default));
  min-width: 0;
}
.cbf-summary .cbf-doc-link {
  color: var(--color-background-brand);
  text-decoration: underline;
}
.cbf-summary__subtable {
  width: 100%;
  border-collapse: collapse;
}
.cbf-summary__subtable th,
.cbf-summary__subtable td {
  text-align: left;
  padding: var(--spacing-200) var(--spacing-300);
  border: 1px solid var(--color-border-default);
  font-size: var(--font-size-150, 0.875rem);
  vertical-align: top;
}
.cbf-summary__subtable th {
  background: var(--color-background-elevation-sunken, #f4f4f4);
  font-weight: var(--typography-font-weight-semibold);
  white-space: nowrap;
}
.cbf-summary__desc-lede {
  margin: 0 0 var(--spacing-200);
}
.cbf-summary__desc {
  margin: 0;
  color: var(--color-content-default-secondary);
  max-width: 80ch;
}
.cbf-summary__note {
  display: block;
  margin-top: 2px;
  color: var(--color-content-default-tertiary);
}
.cbf-summary__map {
  width: 320px;
  flex: none;
}
.cbf-summary__map-canvas {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 220px;
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  background:
    repeating-linear-gradient(
      0deg,
      transparent 0 23px,
      color-mix(in srgb, var(--color-background-brand) 6%, transparent) 23px 24px
    ),
    repeating-linear-gradient(
      90deg,
      transparent 0 23px,
      color-mix(in srgb, var(--color-background-brand) 6%, transparent) 23px 24px
    ),
    color-mix(
      in srgb,
      var(--color-content-utility-success, #15803d) 8%,
      var(--color-background-elevation-raised)
    );
}
.cbf-summary__map-cap {
  margin: var(--spacing-200) 0 0;
  font-style: italic;
  color: var(--color-content-default-tertiary);
}
.cbf-summary .esa-collapsible + .esa-collapsible {
  margin-top: var(--spacing-300);
}
.cbf-lipd__intro {
  margin: 0;
  color: var(--color-content-default-secondary);
  max-width: 90ch;
}
.cbf-lipd__toolbar {
  align-items: center;
}
.cbf-lipd__doctable {
  overflow: visible;
}
.cbf-doc-table__menu-col {
  width: 48px;
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
.cbf-doc-table__title {
  font-weight: var(--typography-font-weight-medium);
}
.cbf-doc-link {
  color: var(--color-background-brand);
  text-decoration: underline;
}
.cbf-lipd .cbf-check {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-100);
  color: var(--color-content-utility-success, #15803d);
  font-weight: var(--typography-font-weight-semibold);
  white-space: nowrap;
}
.cbf-lipd .cbf-na {
  color: var(--color-content-default-tertiary);
  font-style: italic;
}
.cbf-lipd__status {
  align-items: end;
  gap: var(--spacing-400);
  flex-wrap: wrap;
}
.cbf-lipd__status-facts {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-500);
  color: var(--color-content-default-secondary);
}
.cbf-lipd__status-rev {
  min-width: 320px;
}
.cbf-lipd__scroll {
  overflow-x: auto;
}
.cbf-edit__lede {
  margin: 0;
  color: var(--color-content-default-secondary);
}
.cbf-edit__section {
  display: flex;
  gap: var(--spacing-400);
  padding-block: var(--spacing-300);
  border-top: 1px solid var(--color-border-default-subtle, var(--color-border-default));
}
.cbf-edit__num {
  flex: none;
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-full, 9999px);
  background: var(--color-background-elevation-sunken, #f4f4f4);
  color: var(--color-content-default-secondary);
  font-weight: var(--typography-font-weight-semibold);
}
.cbf-edit__fields {
  flex: 1;
  min-width: 0;
}
.cbf-edit__specs {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: var(--spacing-300) var(--spacing-500);
}
.cbf-edit__specs > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.cbf-edit__label {
  font-size: var(--font-size-100, 0.8125rem);
  color: var(--color-content-default-tertiary);
}
.cbf-edit__guidance {
  margin: var(--spacing-300) 0 0;
  color: var(--color-content-default-tertiary);
}
.cbf-edit__file {
  margin: 0;
}
.cbf-edit__newfile {
  margin: 0;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-background-brand);
}
.cbf-edit__history {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: var(--spacing-300) var(--spacing-500);
  padding: var(--spacing-400);
  border-radius: var(--radius-200);
  background: var(--color-background-elevation-sunken, #f4f4f4);
}
.cbf-edit__history > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.cbf-edit__footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--spacing-300);
  width: 100%;
}
.cbf-edit__footer [data-save-hint] {
  margin-inline-end: auto;
  color: var(--color-content-default-tertiary);
}
.cbf-nav-collapsible {
  display: contents;
}
.esa-nav-dropdown .esa-button__native > .esa-icon:last-child {
  transition: transform 0.15s ease;
}
.cbf-nav-burger {
  display: none;
}
.cbf-nav-actions {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-600);
}
.cbf-nav-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: inherit;
  background: none;
  border: 0;
  font-size: 16px;
  font-weight: var(--typography-font-weight-medium);
  white-space: nowrap;
}
.cbf-nav-link .cbf-icon {
  display: inline-flex;
  align-items: center;
}
.cbf-nav-link--user {
  position: relative;
  padding-left: var(--spacing-500);
}
.cbf-nav-link--user:before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 1px;
  height: 1.1em;
  background: #ffffff40;
}
.esa-badge {
  --_badge-bg: var(--badge-bg, var(--color-background-brand, #46a758));
  --_badge-text: var(--badge-text-color, var(--color-content-default-knockout, #fcfcfc));
  --_badge-padding-y: var(--spacing-150, 0.375rem);
  --_badge-padding-x: var(--spacing-200, 0.5rem);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: calc(1lh + 2 * var(--_badge-padding-y));
  padding-block: var(--_badge-padding-y);
  padding-inline: var(--_badge-padding-x);
  border-radius: var(--radius-chip, var(--radius-sm, 0.25rem));
  background: var(--_badge-bg);
  color: var(--_badge-text);
  white-space: nowrap;
  box-sizing: border-box;
}
.esa-badge--lg {
  --_badge-padding-y: var(--spacing-250, 0.625rem);
  --_badge-padding-x: var(--spacing-300, 0.75rem);
}
.esa-badge--warning {
  --_badge-bg: var(--color-background-utility-warning-muted, #fff7c2);
  --_badge-text: var(--color-content-utility-warning, #ab6400);
  --_badge-border: var(--color-border-utility-warning, #f3d673);
}
.esa-badge--success:not(.esa-badge--dot),
.esa-badge--warning:not(.esa-badge--dot),
.esa-badge--danger:not(.esa-badge--dot),
.esa-badge--info:not(.esa-badge--dot) {
  border: 1px solid var(--_badge-border, transparent);
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  border: 0;
  overflow: hidden;
  white-space: nowrap;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
}
.typography-microcopy-xs-strong {
  font-family: var(--typography-microcopy-xs-strong-font-family);
  font-size: var(--typography-microcopy-xs-strong-font-size);
  font-weight: var(--typography-microcopy-xs-strong-font-weight);
  line-height: var(--typography-microcopy-xs-strong-line-height);
  letter-spacing: var(--typography-microcopy-xs-strong-letter-spacing);
}
.typography-microcopy-xs {
  font-family: var(--typography-microcopy-xs-font-family);
  font-size: var(--typography-microcopy-xs-font-size);
  font-weight: var(--typography-microcopy-xs-font-weight);
  line-height: var(--typography-microcopy-xs-line-height);
  letter-spacing: var(--typography-microcopy-xs-letter-spacing);
}
.typography-microcopy-md {
  font-family: var(--typography-microcopy-md-font-family);
  font-size: var(--typography-microcopy-md-font-size);
  font-weight: var(--typography-microcopy-md-font-weight);
  line-height: var(--typography-microcopy-md-line-height);
  letter-spacing: var(--typography-microcopy-md-letter-spacing);
}
.typography-microcopy-md-subtle {
  font-family: var(--typography-microcopy-md-subtle-font-family);
  font-size: var(--typography-microcopy-md-subtle-font-size);
  font-weight: var(--typography-microcopy-md-subtle-font-weight);
  line-height: var(--typography-microcopy-md-subtle-line-height);
  letter-spacing: var(--typography-microcopy-md-subtle-letter-spacing);
}
.typography-body-md {
  font-family: var(--typography-body-md-font-family);
  font-size: var(--typography-body-md-font-size);
  font-weight: var(--typography-body-md-font-weight);
  line-height: var(--typography-body-md-line-height);
  letter-spacing: var(--typography-body-md-letter-spacing);
}
.esa-collapsible {
  border: var(--border-width-default, 1px) solid var(--color-border-default, #cecece);
  border-radius: var(--radius-md, 0.5rem);
  background: var(--color-background-elevation-raised, #fcfcfc);
}
.esa-collapsible__summary {
  display: flex;
  align-items: center;
  gap: var(--spacing-200, 0.5rem);
  padding: var(--spacing-300, 0.75rem) var(--spacing-400, 1rem);
  color: var(--color-content-default, #202020);
  cursor: pointer;
  list-style: none;
}
.esa-collapsible__summary:after {
  content: "";
  width: 8px;
  height: 8px;
  border-right: 2px solid var(--color-content-default-secondary, #646464);
  border-bottom: 2px solid var(--color-content-default-secondary, #646464);
  transform: rotate(-45deg);
  transition: transform 0.15s ease;
  margin-left: auto;
}
.esa-collapsible[open] > .esa-collapsible__summary:after {
  transform: rotate(45deg);
}
.esa-collapsible__body {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-400, 1rem);
  padding: 0 var(--spacing-400, 1rem) var(--spacing-400, 1rem);
}
.esa-alert-box {
  --_alert-bg: var(--color-background-utility-info-subtle, #fbfdff);
  --_alert-border: var(--color-border-utility-info, #acd8fc);
  --_alert-accent: var(--color-content-utility-info, #0d74ce);
  --_alert-icon-color: var(--_alert-accent);
  --_alert-title-color: var(--_alert-accent);
  --_alert-text-color: var(--alert-box-text-color, var(--color-content-default-secondary, #646464));
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-300, 0.75rem);
  padding: var(--spacing-300, 0.75rem) var(--spacing-400, 1rem);
  border: var(--border-width-default, 1px) solid var(--_alert-border);
  border-radius: var(--radius-md, 0.5rem);
  background: var(--_alert-bg);
}
.esa-alert-box--success {
  --_alert-bg: var(--color-background-utility-success-subtle, #fbfefc);
  --_alert-border: var(--color-border-utility-success, #adddc0);
  --_alert-accent: var(--color-content-utility-success, #218358);
}
.esa-alert-box__icon {
  flex-shrink: 0;
  color: var(--_alert-icon-color);
  padding-top: 1px;
}
.esa-alert-box__body {
  flex: 1;
  min-width: 0;
}
.esa-alert-box__title {
  display: block;
  color: var(--_alert-title-color);
  margin-bottom: var(--spacing-050, 0.125rem);
}
.esa-alert-box__message {
  color: var(--_alert-text-color);
}
.esa-button {
  --_btn-pad-y: var(--spacing-300, 0.75rem);
  --_btn-padding-x: var(--spacing-300, 0.75rem);
  --_btn-radius: var(--button-radius-md, 0.5rem);
  --_accent: var(--color-background-brand, #46a758);
  --_accent-hover: var(--color-background-brand-hover, #3e9b4f);
  --_on: var(--color-content-default-knockout, #fcfcfc);
  --_accent-text: var(--_accent);
  --_btn-tint-hover: color-mix(in srgb, var(--_accent) 8%, transparent);
  --_btn-tint-active: color-mix(in srgb, var(--_accent) 14%, transparent);
  display: inline-block;
}
.esa-button--sm {
  --_btn-pad-y: var(--spacing-250, 0.625rem);
  --_btn-padding-x: var(--spacing-250, 0.625rem);
  --_btn-radius: var(--button-radius-sm, 4px);
}
.esa-button__native {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-200, 8px);
  width: 100%;
  padding-block: var(--_btn-pad-y);
  padding-inline: var(--_btn-padding-x);
  border: var(--border-width-default, 1px) solid transparent;
  border-radius: var(--_btn-radius);
  text-decoration: none;
  cursor: pointer;
  transition:
